"""Contact sheet rows for substitute teachers."""

from typing import List, Sequence, Tuple

from rosterkit.models import Student
from rosterkit.errors import ProjectError

GAP = "  "

def _name_key(student: Student) -> Tuple[str, str, str]:
    return (
        student.last_name.lower(),
        student.first_name.lower(),
        student.student_id
    )

def _check(students: Sequence[Student]) -> None:
    if not students:
        raise ProjectError("no students for contact sheet")
    for item in students:
        if not (item.email or "").strip():
            name = item.display_name
            raise ProjectError(f"no email for {name}")

def _widths(students: Sequence[Student]) -> List[int]:
    columns = (
        [item.display_name for item in students],
        [item.section for item in students]
    )
    return [max(map(len, column)) for column in columns]

def _format_row(student: Student, widths: List[int]) -> str:
    name = student.display_name.ljust(widths[0])
    section = student.section.ljust(widths[1])
    return GAP.join([name, section, student.email.strip()])

# ---
def contact_rows(students: Sequence[Student]) -> List[str]:
    """Text rows of name, section and email, sorted by name.

    Raises ProjectError for an empty list or for a student
    without an email, naming that student.
    """
    _check(students)
    ordered = sorted(students, key=_name_key)
    widths = _widths(ordered)
    return [_format_row(item, widths) for item in ordered]
